function [coeff_v, fracRmsError] = harmonicTransform2_xh(F_v, theta_v, phi_v, maxOrder, realFlag, evenOrderFitFlag)% Usage: [coeff_v, fracRmsError] = harmonicTransform2_xh(F_v, theta_v, phi_v, maxOrder, realFlag, evenOrderFitFlag)%% harmonicTransformX finds the spherical harmonic decomposition of% a function F(theta, phi) in terms of the Ylm through order <maxOrder>.% The nth element of F_v is the value of the function at angles% theta = theta_v(n) and phi = phi_v(n). The output is a column % vector of (complex) expansion coefficients and the fractional % mean squared error in the fit.% % based on harmonicTransform3.m% modification: accomodate real SHs%% ver2: add evenOrderFitFlag as input% Make sure input vectors are columns. F_v first:if (size(F_v, 1) < size(F_v, 2))	F_v = F_v.';end% Now theta_v:if (size(theta_v, 1) < size(theta_v, 2))	theta_v = theta_v.';end% And phi_v:if (size(phi_v, 1) < size(phi_v, 2))	phi_v = phi_v.';endif ~exist('realFlag')    realFlag = 0;end% Get real design matrix:gridFlag = 0;% evenOrderFitFlag = 0;design_m = sphericalHarm_xh5(theta_v, phi_v, maxOrder, gridFlag, evenOrderFitFlag, realFlag);% Now solve least squares problem to get expansion coefficients:coeff_v = pinv(design_m.' * design_m) * (design_m.') * F_v;% coeff_v = (design_m.' * design_m) \ (design_m.') * F_v;% Find residuals and error in fit:fFit_v = design_m * coeff_v;residual_v = fFit_v - F_v;fracRmsError = sqrt(mean(residual_v.^2) / mean(F_v.^2));